package httpapi

import (
	_ "embed" // the generated OpenAPI spec is part of the binary

	"github.com/gofiber/fiber/v3"
)

// openapiSpec is generated by `make swagger` from the handler annotations. Commit it; the test
// TestSwaggerListsEveryRoute fails when a route is missing from it.
//
//go:embed openapi/swagger.json
var openapiSpec []byte

// swaggerUIPage loads Swagger UI from a pinned CDN version and points it at /docs/openapi.json.
const swaggerUIPage = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>API docs</title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5.17.14/swagger-ui.css">
</head>
<body>
<div id="swagger-ui"></div>
<script src="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5.17.14/swagger-ui-bundle.js"></script>
<script>
window.ui = SwaggerUIBundle({url: "/docs/openapi.json", dom_id: "#swagger-ui"});
</script>
</body>
</html>`

// registerDocs serves Swagger UI at /docs and the spec at /docs/openapi.json. Both are public.
func registerDocs(app *fiber.App) {
	app.Get("/docs", func(c fiber.Ctx) error {
		c.Set(fiber.HeaderContentType, fiber.MIMETextHTMLCharsetUTF8)

		return c.SendString(swaggerUIPage)
	})
	app.Get("/docs/openapi.json", func(c fiber.Ctx) error {
		c.Set(fiber.HeaderContentType, fiber.MIMEApplicationJSONCharsetUTF8)

		return c.Send(openapiSpec)
	})
}
